) p ON p.item_id = pm.order_item_id
JOIN `35pf_woocommerce_order_items` oi ON oi.order_item_id = p.item_id
 AND oi.order_id = p.order_id
 AND oi.order_item_type = 'line_item'
 AND BINARY SHA2(REPLACE(oi.order_item_name, ' ', ' '), 256) = BINARY p.title_hash
JOIN `35pf_woocommerce_order_itemmeta` src
  ON src.order_item_id = p.item_id AND src.meta_key = '_company_source_line_item_id'
 AND CAST(src.meta_value AS UNSIGNED) = p.source_item_id
LEFT JOIN `35pf_woocommerce_order_itemmeta` duplicate_pm
  ON duplicate_pm.order_item_id = pm.order_item_id
 AND duplicate_pm.meta_key = '_zb_torob_purchase_price' AND duplicate_pm.meta_id <> pm.meta_id
SET pm.meta_value = CAST(p.price AS CHAR)
WHERE pm.meta_key = '_zb_torob_purchase_price'
  AND (pm.meta_value IS NULL OR TRIM(pm.meta_value) = '' OR UPPER(TRIM(pm.meta_value)) = 'NULL')
  AND duplicate_pm.meta_id IS NULL
  AND (p.needs_single_item = 0 OR
 (SELECT COUNT(*) FROM `35pf_woocommerce_order_items` sibling
   WHERE sibling.order_id = p.order_id AND sibling.order_item_type = 'line_item') = 1);

