SELECT 117, 58897, 34742, 3325294, 10532, 2057505, 2057505, 0, 'aylinarshi2@gmail.com', 'df9fbb43ab5ca710d3b67e48cc263e1c383d816ac083c99ccd18e92c27cafc5d', 1, 0, ''
UNION ALL
SELECT 73, 34753, 34753, 3325341, 10552, 860000, 860000, 0, 'mehraban', 'a832e54fd1b43616d4d4daf6ca5d2293c69deb0d4c885851235d187422089162', 1, 0, ''
UNION ALL
SELECT 190, 413025, 34758, 3325362, 67831, 10800000, 10800000, 0, 'hossein.ghanbari137877@gmail.com', '0fb37ba00698b8c8fddaf0287733e0fab174ef96483ebde0fabb450124f7a246', 1, 0, ''
UNION ALL
SELECT 74, 34779, 34779, 3325468, 10589, 560000, 560000, 0, 'mehraban', 'a6cade20b0c2291c09326a69f6a01f0ede2846d1068f779a821ba00854c7047d', 1, 0, ''
) p
JOIN `35pf_woocommerce_order_items` oi ON oi.order_item_id = p.item_id
 AND oi.order_id = p.order_id
 AND oi.order_item_type = 'line_item'
 AND BINARY SHA2(REPLACE(oi.order_item_name, ' ', ' '), 256) = BINARY p.title_hash
WHERE EXISTS (SELECT 1 FROM `35pf_woocommerce_order_itemmeta` src
        WHERE src.order_item_id = p.item_id
          AND src.meta_key = '_company_source_line_item_id'
          AND CAST(src.meta_value AS UNSIGNED) = p.source_item_id)
  AND (p.needs_single_item = 0 OR
 (SELECT COUNT(*) FROM `35pf_woocommerce_order_items` sibling
   WHERE sibling.order_id = p.order_id AND sibling.order_item_type = 'line_item') = 1)
  AND NOT EXISTS (SELECT 1 FROM `35pf_woocommerce_order_itemmeta` pm
                  WHERE pm.order_item_id = p.item_id AND pm.meta_key = '_zb_torob_purchase_price');

COMMIT;
